const normalizeName = (name: string) => name.toLowerCase().normalize('NFKD').replace(/[\\u0300-\\u036f]/g, '').replace(/[^a-z0-9]/g, '');
const byNormalizedName = new Map(records.map((record) => [normalizeName(record.name), record]));

// Explicit, reviewed name-resolution for Cricsheet scorecard names and common aliases.
const nameAliases: Record<string, string> = {"Suryakumar Yadav":"SA Yadav","Robin Minz":"R Minz","Deepak Chahar":"D L Chahar","Raj Angad Bawa":"RA Bawa","Mahipal Lomror":"M K Lomror","Ruturaj Gaikwad":"R D Gaikwad","Khaleel Ahmed":"S K K Ahmed","Rahul Chahar":"R D Chahar","Ayush Mhatre":"A Mhatre","Anshul Kamboj":"A Kamboj","Matt Henry":"Matthew Henry","Spencer Johnson":"SH Johnson","Shreyas Gopal":"R Shreyas Gopal","Matthew Short":"Matt Short","Kuldeep Yadav":"Kuldeep Singh Yadav","T Natarajan":"Thangarasu Natarajan","Vipraj Nigam":"V Nigam","Nehal Wadhera":"N Wadhera","Praveen Dubey":"Pravin Dubey","Yash Ravisingh Thakur":"Yash Thakur","Varun Chakaravarthy":"V Chakravarthy","Matheesha Pathirana":"M Pathirana","Angkrish Raghuvanshi":"A Raghuvanshi","Rovman Powell":"R Powell","Rahul Tripathi":"R A Tripathi","Tim Seifert":"TL Seifert","Vaibhav Arora":"Vaibhav G Arora","Phil Salt":"Philip Salt","Krunal Pandya":"K H Pandya","Nuwan Thushara":"N Thushara","Jacob Bethell":"JG Bethell","Romario Shepherd":"R Shepherd","Nitish Kumar Reddy":"K Nithish Kumar Reddy","Harshal Patel":"H V Patel","Eshan Malinga":"E Malinga","Rahul Tewatia":"R K Tewatia","Shahrukh Khan":"M Shahrukh Khan","Washington Sundar":"MS Washington Sundar","Prasidh Krishna":"M Prasidh Krishna","Luke Wood":"L Wood","Sai Kishore":"R Sai Kishore","Manav Suthar":"MJ Suthar","Manimaran Siddharth":"M Siddharth","Digvesh Singh Rathi":"DS Rathi","Sai Sudharsan":"B Sai Sudharsan","Steve Smith":"Steven Smith","Harry Brook":"HC Brook","Nandre Burger":"N Burger","Michael Bracewell":"MG Bracewell","Maheesh Theekshana":"M Theekshana","Obed McCoy":"OC McCoy"};

export function getIPLcareerStats(playerName: string): IPLCareerStats | undefined {
  const sourceName = nameAliases[playerName] || playerName;
  return byNormalizedName.get(normalizeName(sourceName));
}
